import {AppState} from 'react-native';
import {FormaError, resolveCalendarRange} from '@forma/core';
import type {Workout, WorkoutSet} from '@forma/core';
import {parsePreferences} from '@forma/mobile-host';
import type {MobileHost} from '@forma/mobile-host';
import {deviceAdapters} from './adapters/device';
import {mobileRoot} from './root';
// @ts-ignore Generated by the build runner; excluded from Git.
import metadata from '../mobile-build.json';

import counts from '../host-gate-counts.json';
export const HOST_GATE_COUNTS = counts;
interface SavedGate {
  runId: string;
  created: Workout;
  set: WorkoutSet;
  liveStarted: Workout;
  finishedCurrent: Workout;
  liveCurrent: Workout;
}
function cycle(): Promise<void> {
  return new Promise((resolve, reject) => {
    let background = false;
    const subscription = AppState.addEventListener('change', state => {
      if (state === 'background') background = true;
      if (state === 'active' && background) {clearTimeout(timer); subscription.remove(); resolve();}
    });
    const timer = setTimeout(() => {subscription.remove(); reject(new Error('No actual background/resume cycle within 60 seconds.'));}, 60000);
  });
}
export async function runHostGate(host: MobileHost, mode: string, runId: string): Promise<void> {
  let count = 0;
  const check = (value: unknown, message: string) => {if (!value) throw new Error(message); count++;};
  const same = (actual: unknown, expected: unknown, message: string) => check(JSON.stringify(actual) === JSON.stringify(expected), message);
  const rejects = async (run: () => unknown, code: FormaError['code'], field?: string) => {
    let failure: unknown; try {await run();} catch (error) {failure = error;}
    check(failure instanceof FormaError && failure.code === code && (field === undefined || failure.field === field), 'Expected typed error ' + code + ' on ' + field);
  };
  const request = (suffix: string) => 'hostgate.' + runId + '.' + suffix;
  try {
    if (!deviceAdapters.isHostGate()) throw new Error('Gate requires the isolated native build.');
    await host.start();
    const service = host.service();
    if (mode === 'fixtures') {
      check(mobileRoot() === host && mobileRoot() === host, 'Root singleton changed.');
      const ids = [deviceAdapters.ids.next(), deviceAdapters.ids.next(), deviceAdapters.ids.next()];
      check(new Set(ids).size === 3 && ids.every(id => /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)), 'Native UUID failure.');
      const range = resolveCalendarRange({nowUtc: deviceAdapters.platform.nowUtc(), timeZone: deviceAdapters.platform.timeZone(), period: 'today'});
      check(host.snapshot().calendar?.timeZone === range.timeZone && host.snapshot().calendar?.period === 'today', 'Native timezone/calendar failure.');
      check((await service.exercises.list()).length === 19, 'Catalog count changed.');
      check((await service.splitDays.list()).length === 3, 'Split count changed.');
      await host.setTheme('dark');
      check(host.snapshot().preferences.theme === 'dark' && parsePreferences(deviceAdapters.preferences.read()).theme === 'dark', 'Preference save/publication mismatch.');
      await rejects(() => host.setTheme('invalid' as never), 'INVALID_INPUT', 'theme');
      await rejects(() => service.workouts.history({dateFrom: 'not-a-date'}), 'INVALID_INPUT', 'dateFrom');
      const before = await service.workouts.list(); host.background(); await host.resume();
      same(await service.workouts.list(), before, 'Host resume changed records.');
      const pending = service.workouts.create({requestId: request('drain'), date: '2026-10-12'});
      const closing = host.close();
      check((await pending).date === '2026-10-12', 'Accepted write did not drain.'); await closing;
      await rejects(() => host.service(), 'SERVICE_CLOSED');
      await rejects(() => host.start(), 'SERVICE_CLOSED');
    } else if (mode === 'seed') {
      // Previous successful test sessions are synthetic. Finish only that known test session.
      const previous = await service.workouts.inProgress();
      if (previous) {
        if (!previous.notes?.startsWith('Forma host gate ')) throw new Error('Unexpected record in the isolated test sandbox.');
        await service.workouts.finish({requestId: request('previous.finish'), workoutId: previous.id});
      }
      const created = await service.workouts.create({requestId: request('create'), date: '2026-10-12', notes: 'Forma host gate ' + runId});
      const set = await service.workouts.addSet({requestId: request('set'), workoutId: created.id, exerciseId: 'leg-curls', reps: 10, weightKg: 20, loadConvention: 'entered'});
      const liveStarted = await service.workouts.start({requestId: request('start'), date: '2026-10-13', notes: 'Forma host gate ' + runId});
      await service.workouts.addSet({requestId: request('live.set'), workoutId: liveStarted.id, exerciseId: 'leg-extensions', reps: 8, weightKg: 30});
      const finishedCurrent = await service.workouts.get(created.id);
      const liveCurrent = await service.workouts.get(liveStarted.id);
      check(finishedCurrent.sets.length === 1, 'Finished synthetic record not saved.');
      check(liveCurrent.status === 'in-progress' && liveCurrent.sets.length === 1 && liveCurrent.finishedAt === null, 'Live record not saved.');
      await host.setTheme('light');
      check(parsePreferences(deviceAdapters.preferences.read()).theme === 'light', 'Native theme not persisted.');
      const wait = cycle(); console.info('FORMA_HOST_READY ' + runId); await wait;
      await host.resume();
      same(await service.workouts.get(created.id), finishedCurrent, 'Finished record changed across actual background/resume.');
      same(await service.workouts.get(liveStarted.id), liveCurrent, 'Live record changed across actual background/resume.');
      const marker: SavedGate = {runId, created, set, liveStarted, finishedCurrent, liveCurrent};
      check(deviceAdapters.gateSnapshots.write(JSON.stringify(marker)), 'Expected snapshots were not confirmed on disk.');
      // Leave the native database open. The runner force-stops this process next.
    } else if (mode === 'verify') {
      const text = deviceAdapters.gateSnapshots.read();
      if (!text) throw new Error('No seed marker survived restart.');
      const saved = JSON.parse(text) as SavedGate;
      check(saved.runId === runId, 'Seed marker belongs to another run.');
      // Read BEFORE any replay. Missing primary records must fail, never be recreated.
      same(await service.workouts.get(saved.created.id), saved.finishedCurrent, 'Exact finished record did not survive process restart.');
      same(await service.workouts.get(saved.liveStarted.id), saved.liveCurrent, 'Exact live record did not survive process restart.');
      same(await service.workouts.create({requestId: request('create'), date: '2026-10-12', notes: 'Forma host gate ' + runId}), saved.created, 'Original create receipt changed.');
      same(await service.workouts.addSet({requestId: request('set'), workoutId: saved.created.id, exerciseId: 'leg-curls', reps: 10, weightKg: 20, loadConvention: 'entered'}), saved.set, 'Original set receipt changed.');
      same(await service.workouts.start({requestId: request('start'), date: '2026-10-13', notes: 'Forma host gate ' + runId}), saved.liveStarted, 'Original session receipt changed.');
      check(host.snapshot().preferences.theme === 'light' && parsePreferences(deviceAdapters.preferences.read()).theme === 'light', 'Saved theme did not survive restart.');
      check(host.snapshot().calendar?.timeZone === deviceAdapters.platform.timeZone(), 'Native date context not restored.');
    } else throw new Error('Unsupported gate mode.');
    const expected = HOST_GATE_COUNTS[mode as keyof typeof HOST_GATE_COUNTS];
    if (count !== expected) throw new Error('Gate assertion count mismatch: ' + count + ' !== ' + expected);
    console.info('FORMA_HOST_RESULT ' + JSON.stringify({...metadata, mode, runId, ok: true, count}));
  } catch (error) {
    console.info('FORMA_HOST_RESULT ' + JSON.stringify({...metadata, mode, runId, ok: false, count,
      message: error instanceof Error ? error.message.slice(0, 500) : 'Unexpected native gate failure',
      stack: error instanceof Error ? error.stack?.slice(0, 1500) : undefined}));
  }
}
